import json
from unittest.mock import MagicMock

import pytest

from ..strategic_reasoner import StrategicReasoner, StrategicInsight
from ..output_formatter import OutputFormatter
from ..persona_debate import PersonaDebate
from ..adversarial_orchestrator import AdversarialOrchestrator


